 const session=state.sessions.find(s=>s.stationID===closingStationID&&s.completedDay);
 if(!session){view('home');return;}
 const entry=quoteMap?.get(closingStationID),r=D.stationSummary(session),t=catalog.teams.find(t=>t.id===snap.profile.teamID),done=btn(closingReturn==='history'?'返回成绩':'完赛','closing-done',true);
 if(!entry){shell('本站寄语',`<section class="panel center"><h2>第${closingStationID}站，已完赛</h2><p>${quoteError?esc(quoteError):'正在准备本站寄语…'}</p>${quoteError?btn('重新加载寄语','closing-retry'):''}<p>成绩已保存。暂时无法联网时，可以先完赛，稍后从本站成绩回看寄语。</p></section>`,'',done);if(!quoteError)ensureQuotes().then(()=>{if(screen==='closing')render();}).catch(()=>{if(screen==='closing')render();});return;}
