function resetView(){answers={};tabIndex=0;translation=false;passageTranslation=false;audioKey='';studyViewIndex=null;studyExampleIndex=0;player.stop();}
async function commit(fn){if(busy)return false;busy=true;saveError='';paintSaving();try{await ensureAccess();await prepareStoredStations();const previousRoute=state?.route;state=await store.transact(fn);if(['studyCards','warmup','question','correctionQuestion'].includes(previousRoute)&&state.route!== 'schedule')recordActivity();resetView();if(['feedback','correctionFeedback'].includes(state.route)){const feedback=D.snapshot(state,stations.get(state.activeStationID)).feedback;tabIndex=Math.max(0,feedback.findIndex(f=>!f.correct));}screen=null;render();return true;}catch(e){saveError=`保存未完成：${errorText(e)}。输入和选择已保留，请重试原操作。`;if(e.message==='revisionConflict'){modal=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><h2>另一窗口已更新进度</h2><p>本页尚未保存的输入不会覆盖新记录。请重新读取当前存档。</p>${btn('重新读取存档','reload-state',true)}</section></div>`;}render();return false;}finally{busy=false;paintSaving();}}
