 const detail=`<section class="panel schedule-detail"><div class="detail-top"><span class="tag">第${id}站 · ${review?'复习':'新学'}${done?' · 已完赛':''}</span>${snap.currentStationID&&!current?btn('回到当前站',`select:${snap.currentStationID}`):''}</div>${heading}${score}${laps}<div class="word-label">${review?'本站复习内容':'本站新学内容'} · ${list.length}项</div><div class="words-scroll" aria-label="本站词表，可局部滚动"><div class="word-chips">${list.map(i=>`<span>${esc(i.word)}</span>`).join('')||'<p>本站内容待接入，不会开启空任务。</p>'}</div></div><div class="detail-bottom">${done?`${btn('查看本站完整成绩',`result:${id}`)}<p>重练不会改写首次成绩、星级和里程。</p>`:session?`已提交 ${progress} / 24题 · 继续时保留已提交内容。`:'先学一学，再暖一圈，最后迎接三圈挑战。'}</div></section>`;
